const int BUTTON_PIN = 2;    // Кнопка (между пином 2 и GND)
const int MOTOR_PIN = 9;     // Модуль (контакт S)

bool motorState = false;     // Текущее состояние мотора (выдвинут/задвинут)
bool lastButtonState = HIGH; // Предыдущее состояние кнопки (с учетом INPUT_PULLUP)
unsigned long lastDebounceTime = 0; 
const unsigned long DEBOUNCE_DELAY = 50; // Антидребезг 50 мс

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP); // Внутренняя подтяжка к 5V
  pinMode(MOTOR_PIN, OUTPUT);
  digitalWrite(MOTOR_PIN, LOW);      // Изначально мотор выключен
}

void loop() {
  int reading = digitalRead(BUTTON_PIN);

  // Логика антидребезга и отслеживания нажатия
  if (reading != lastButtonState) {
    lastDebounceTime = millis();
  }

  if ((millis() - lastDebounceTime) > DEBOUNCE_DELAY) {
    // Если кнопка была нажата (переход с HIGH на LOW)
    if (reading == LOW && lastButtonState == HIGH) {
      motorState = !motorState; // Меняем состояние (триггер)

      if (motorState) {
        digitalWrite(MOTOR_PIN, HIGH); // Включаем мотор
      } else {
        digitalWrite(MOTOR_PIN, LOW);  // Выключаем мотор
      }
    }
  }

  lastButtonState = reading;
}
